<template><div class="page-head"><div><h2>店铺配置</h2><div class="muted">配置小程序商城顶部展示的信息</div></div><ElButton type="warning" :loading="saving" @click="save">保存配置</ElButton></div><ElCard class="card"><ElForm label-position="top" style="max-width:760px"><ElFormItem label="店铺名称"><ElInput v-model="form.name"/></ElFormItem><ElFormItem label="店铺图片"><div class="image-field"><ElImage v-if="form.logoUrl" :src="form.logoUrl" fit="cover" class="preview"/><ElInput v-model="form.logoUrl" placeholder="上传后自动填写图片地址"/><ElUpload :show-file-list="false" accept="image/*" :http-request="uploadLogo"><ElButton :loading="uploading">上传图片</ElButton></ElUpload></div></ElFormItem><ElFormItem label="店铺介绍"><ElInput v-model="form.description" type="textarea" :rows="4"/></ElFormItem><ElFormItem label="服务标签（用逗号分隔）"><ElInput v-model="tags" placeholder="品质严选,每日发货"/></ElFormItem><ElFormItem label="客服电话"><ElInput v-model="form.servicePhone"/></ElFormItem></ElForm></ElCard></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';const form=reactive<any>({name:'',logoUrl:'',description:'',servicePhone:''}),tags=ref(''),saving=ref(false),uploading=ref(false);onMounted(async()=>{const d:any=await api.store();Object.assign(form,d);try{tags.value=JSON.parse(d.serviceTagsJson||'[]').join(',')}catch{tags.value=''}});async function uploadLogo(o:any){uploading.value=true;try{const d:any=await api.upload(o.file);form.logoUrl=d.url;ElMessage.success('上传成功')}catch(e:any){ElMessage.error(e.message)}finally{uploading.value=false}}async function save(){saving.value=true;try{await api.saveStore({...form,serviceTags:tags.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean)});ElMessage.success('保存成功')}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}</script><style scoped>.image-field{width:100%;display:flex;align-items:center;gap:12px}.preview{width:74px;height:74px;border-radius:12px;flex:none}</style>
